from shiny._utils import rand_hex

# ---
# MOCK DATABASE
# ---

# imagine this is a database query result
items = [
    "item_1",
    "item_2",
    "item_3"
]

# this is a function that runs the query
def get_items():
    return items

# this function deletes items based on the query
